mapper.select:
SELECT R.RSPNS_CN
FROM TB_SURVEY_RESPONSE R
WHERE R.PARENT_TYPE = 'SURVEY'
  AND R.PARENT_SN = #{srvySn}
  AND R.USER_SN = #{userSn}
    LIMIT 1

mapper.update:
UPDATE TB_BBS_SURVEY
SET SRVY_DEL_YN = TRUE,
    SRVY_LAST_MDFCN_DT = NOW()
WHERE SRVY_SN = #{srvySn}
  AND USER_SN = #{userSn}
